    public Channel? Channel { get; init; }

    /// <summary>
    /// 16 kHz samples in them.
    /// </summary>
    [JsonPropertyName("samples")]
    public required long Samples { get; init; }
}

/// <summary>
/// How a record's chunks were placed on its timeline: recorded (from the start the meeting
