/// the shell says so.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<AudioTimeline>))]
public enum AudioTimeline
{
    [JsonStringEnumMemberName("recorded")]
    Recorded,
    [JsonStringEnumMemberName("estimated")]
