[JsonConverter(typeof(StrictEnumConverter<RecordKind>))]
public enum RecordKind
{
    [JsonStringEnumMemberName("dictation")]
    Dictation,
    [JsonStringEnumMemberName("meeting")]
    Meeting,
    [JsonStringEnumMemberName("file_import")]
    FileImport,
}

/// <summary>
/// A note the user typed, stamped with where in the record it was written.
/// </summary>
public sealed record RecordNote
{
    /// <summary>
    /// Where in the record, ms from its start: the timestamp chip.
    /// </summary>
    [JsonPropertyName("at_ms")]
    public required long AtMs { get; init; }

    /// <summary>
    /// Its id.
    /// </summary>
    [JsonPropertyName("note")]
    public required string Note { get; init; }

    /// <summary>
    /// The note. The user's words: never log it.
    /// </summary>
    [JsonPropertyName("text")]
    public required string Text { get; init; }
}

/// <summary>
/// A record as a list shows it.
/// </summary>
public sealed record RecordRow
{
    /// <summary>
    /// When it ended, Unix ms; absent while it is live.
    /// </summary>
    [JsonPropertyName("ended_at_unix_ms")]
    public long? EndedAtUnixMs { get; init; }

    /// <summary>
    /// Whether it kept audio (a meeting's chunks).
    /// </summary>
    [JsonPropertyName("has_audio")]
    public required bool HasAudio { get; init; }

    /// <summary>
    /// What produced it.
    /// </summary>
    [JsonPropertyName("kind")]
    public required RecordKind Kind { get; init; }

    /// <summary>
    /// The first words of an untitled record's transcript. Carries the user's words: never log
    /// it.
    /// </summary>
    [JsonPropertyName("preview")]
    public string? Preview { get; init; }

    /// <summary>
    /// Its id.
    /// </summary>
    [JsonPropertyName("record")]
    public required string Record { get; init; }

    /// <summary>
    /// The transcript revision: 1 while live, 2 once the final pass replaced it.
    /// </summary>
    [JsonPropertyName("revision")]
    public required long Revision { get; init; }

    /// <summary>
    /// The application involved, when known.
    /// </summary>
    [JsonPropertyName("source_app")]
    public string? SourceApp { get; init; }

    /// <summary>
    /// When it started, Unix ms.
    /// </summary>
    [JsonPropertyName("started_at_unix_ms")]
    public required long StartedAtUnixMs { get; init; }

    /// <summary>
    /// Its title: a calendar event's, a file's name, or the summary's headline. Absent until
    /// one is known.
    /// </summary>
    [JsonPropertyName("title")]
    public string? Title { get; init; }
}

/// <summary>
/// Settled transcript on a record's timeline. Carries the user's words: never log it.
/// </summary>
public sealed record RecordSegment
{
    /// <summary>
    /// Mic (you) or far end (them).
    /// </summary>
    [JsonPropertyName("channel")]
    public required Channel Channel { get; init; }

    /// <summary>
    /// End, ms from the record's start.
    /// </summary>
    [JsonPropertyName("end_ms")]
    public required long EndMs { get; init; }

    /// <summary>
    /// The diarized far-end speaker, when labels were kept.
    /// </summary>
    [JsonPropertyName("speaker")]
    public string? Speaker { get; init; }

    /// <summary>
    /// Start, ms from the record's start.
    /// </summary>
    [JsonPropertyName("start_ms")]
    public required long StartMs { get; init; }

    /// <summary>
    /// The words.
    /// </summary>
    [JsonPropertyName("text")]
    public required string Text { get; init; }
}

/// <summary>
/// A record's summary, as stored: markdown (a headline, then sections). Shells render it; it is
/// never shown raw.
/// </summary>
public sealed record RecordSummary
{
    /// <summary>
    /// When it was written, Unix ms.
    /// </summary>
    [JsonPropertyName("created_at_unix_ms")]
    public required long CreatedAtUnixMs { get; init; }

    /// <summary>
    /// Its decisions and actions with the line each cites, in the order the text lists them
    /// (empty for a summary saved before they were kept).
    /// </summary>
    [JsonPropertyName("items")]
    public required global::System.Collections.Generic.IReadOnlyList<SummaryItemRow> Items { get; init; }

    /// <summary>
    /// The model that wrote it.
    /// </summary>
    [JsonPropertyName("model")]
    public required string Model { get; init; }

    /// <summary>
    /// The markdown. The library's words: never log it.
    /// </summary>
    [JsonPropertyName("text")]
    public required string Text { get; init; }
}

/// <summary>
/// Why a job's model was refused.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<Refusal>))]
public enum Refusal
{
    [JsonStringEnumMemberName("updating")]
    Updating,
}

/// <summary>
/// A you line the final pass removed as echo of the far end. Its words are not here: the store
/// keeps the line with the record, at index in its removed lines (by start time), so it can be
/// put back.
/// </summary>
public sealed record RemovedEchoLine
{
    /// <summary>
    /// Its end.
    /// </summary>
    [JsonPropertyName("end_ms")]
    public required long EndMs { get; init; }

    /// <summary>
    /// The far-end lines whose words it matched, in time order.
    /// </summary>
    [JsonPropertyName("far")]
    public required global::System.Collections.Generic.IReadOnlyList<EchoSpan> Far { get; init; }

    /// <summary>
    /// Its place in the record's removed lines.
    /// </summary>
    [JsonPropertyName("index")]
    public required long Index { get; init; }

    /// <summary>
    /// How many of them matched the far end, in order.
    /// </summary>
    [JsonPropertyName("matched")]
    public required long Matched { get; init; }

    /// <summary>
    /// Its start, ms into the meeting.
    /// </summary>
    [JsonPropertyName("start_ms")]
    public required long StartMs { get; init; }

    /// <summary>
    /// Its words, normalised.
    /// </summary>
    [JsonPropertyName("words")]
    public required long Words { get; init; }
}

/// <summary>
/// How much confirmation a voice command needs: safe runs at once, moderate gets a brief notice
/// the user can cancel, dangerous asks first.
/// </summary>
[JsonConverter(typeof(StrictEnumConverter<Risk>))]
public enum Risk
{
    [JsonStringEnumMemberName("safe")]
    Safe,
    [JsonStringEnumMemberName("moderate")]
    Moderate,
    [JsonStringEnumMemberName("dangerous")]
    Dangerous,
    [JsonStringEnumMemberName("other")]
    Other,
}

/// <summary>
/// A full-text match.
/// </summary>
public sealed record SearchHit
{
    /// <summary>
    /// The record.
    /// </summary>
    [JsonPropertyName("record")]
